def CountVowels(s):
    c=0
    for ch in range(s):
        if 'aeiouAEIOU' in ch:
            c=+1
    return(ch)

acceptedAlternatives:
def CountVowels(s):
    c=0
    for ch in s:
        if ch.lower() in 'aeiou':
            c=c+1
    return c

def CountVowels(s):
    c=0
    for i in range(len(s)):
        if s[i] in 'aeiouAEIOU':
            c+=1
    return c

